#!/usr/bin/env python3
"""Generate independent IERS fixtures; downloads/build products stay outside Git.

This original Tudat driver tooling is neither supplied nor endorsed by IERS.
The reference algorithms and their source files remain unmodified.
"""

import argparse
import csv
import hashlib
import io
import json
from pathlib import Path
import subprocess
import urllib.request

HERE = Path(__file__).resolve().parent


def generate_header(inputs, outputs):
    text = [
        "// clang-format off",
        "// Generated by generate.py from unmodified IERS reference software.",
        "// See README.md and sources.json for provenance. Do not edit by hand.",
        "#ifndef TUDAT_IERS2010_REFERENCE_FIXTURES_H",
        "#define TUDAT_IERS2010_REFERENCE_FIXTURES_H",
        "#include <array>",
        "namespace iers2010_reference {",
        "struct Fixture {",
        "    const char* name;",
        "    double utcSeconds, ttSeconds;",
        "    std::array< double, 3 > station, sun, moon, displacement, diurnal, longPeriod;",
        "};",
        "static const std::array< Fixture, %d > fixtures = {{" % len(inputs),
    ]
    for inp, out in zip(inputs, outputs):
        text.append(
            '    { "%s", %s, %s,'
            % (inp["name"], out["utc_seconds_since_j2000"], out["tt_seconds_since_j2000"])
        )
        vectors = [
            [inp[body + "_" + axis + "_m"] for axis in "xyz"] for body in ("station", "sun", "moon")
        ]
        vectors += [
            [out[prefix + "d" + axis + "_m"] for axis in "xyz"]
            for prefix in ("", "diurnal_", "long_")
        ]
        text.append(
            "      " + ",\n      ".join("{{ " + ", ".join(v) + " }}" for v in vectors) + " },"
        )
    text += ["}};", "} // namespace iers2010_reference", "#endif", "// clang-format on", ""]
    return "\n".join(text)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--reference-dir",
        type=Path,
        required=True,
        help="External local cache for IERS sources and executable; must be outside this repository",
    )
    parser.add_argument("--compiler", default="gfortran")
    parser.add_argument(
        "--download", action="store_true", help="Download missing pinned reference files"
    )
    parser.add_argument(
        "--check", action="store_true", help="Verify committed outputs instead of replacing them"
    )
    args = parser.parse_args()
    cache = args.reference_dir.resolve()
    repository = HERE.parents[5]
    if cache == repository or repository in cache.parents:
        parser.error("--reference-dir must be outside the Git repository")
    cache.mkdir(parents=True, exist_ok=True)
    manifest = json.loads((HERE / "sources.json").read_text())
    sources = []
    for name, checksum in manifest["files"].items():
        path = cache / name
        if not path.exists():
            if not args.download:
                parser.error(str(path) + " is missing; pass --download")
            with urllib.request.urlopen(manifest["source_base_url"] + name, timeout=60) as response:
                path.write_bytes(response.read())
        if hashlib.sha256(path.read_bytes()).hexdigest() != checksum:
            raise RuntimeError("Reference checksum mismatch: " + str(path))
        sources.append(str(path))
    executable = cache / "reference_driver"
    subprocess.run(
        [
            args.compiler,
            "-O0",
            "-ffixed-line-length-none",
            "-o",
            str(executable),
            str(HERE / "reference_driver.f90"),
            *sources,
        ],
        check=True,
    )
    inputs = list(csv.DictReader((HERE / "inputs.csv").open()))
    stdin = (
        str(len(inputs))
        + "\n"
        + "\n".join(" ".join(list(row.values())[1:]) for row in inputs)
        + "\n"
    )
    result = subprocess.run(
        [str(executable)], input=stdin, text=True, capture_output=True, check=True
    )
    lines = result.stdout.splitlines()
    if len(lines) != len(inputs):
        raise RuntimeError("Unexpected number of reference rows")
    columns = [
        "name",
        "utc_seconds_since_j2000",
        "tt_seconds_since_j2000",
        "dx_m",
        "dy_m",
        "dz_m",
        "diurnal_dx_m",
        "diurnal_dy_m",
        "diurnal_dz_m",
        "long_dx_m",
        "long_dy_m",
        "long_dz_m",
    ]
    outputs = []
    for inp, line in zip(inputs, lines):
        values = line.split()
        if len(values) != len(columns) - 1:
            raise RuntimeError("Malformed reference output")
        outputs.append(dict(zip(columns, [inp["name"], *values])))
    # Published DEHANTTIDEINEL header cases independently check the executable.
    published = [
        (0.07700420357108125891, 0.06304056321824967613, 0.05516568152597246810),
        (-0.02036831479592075833, 0.05658254776225972449, -0.07597679676871742227),
    ]
    for row, vector in zip(outputs[:2], published):
        for axis, expected in zip("xyz", vector):
            if abs(float(row["d" + axis + "_m"]) - expected) > 1e-15:
                raise RuntimeError("Published IERS benchmark did not reproduce")
    buffer = io.StringIO()
    writer = csv.DictWriter(buffer, fieldnames=columns, lineterminator="\n")
    writer.writeheader()
    writer.writerows(outputs)
    artifacts = {"expected.csv": buffer.getvalue(), "fixtures.h": generate_header(inputs, outputs)}
    for name, text in artifacts.items():
        path = HERE / name
        if args.check:
            if path.read_text() != text:
                raise RuntimeError("Reference artifact differs: " + name)
        else:
            path.write_text(text)
    print(
        ("Verified" if args.check else "Generated") + " %d independent IERS fixtures" % len(inputs)
    )


if __name__ == "__main__":
    main()
